/* Shared website design system */
/* Shared design system. This is the final layer in css/site.css. */
html[data-wissen-global] body.wissen-global-type {
  --wissen-bg: #080809;
  --wissen-section-space: 3rem;
  --section-edge: var(--wissen-section-space);
  --wissen-hero: clamp(2.5rem, calc(.970588rem + 4.705882vw), 4.5rem);
  --wissen-section-title: clamp(1.875rem, calc(1.014706rem + 2.647059vw), 3rem);
  --wissen-feature-title: clamp(1.375rem, calc(1.279412rem + .294118vw), 1.5rem);
  --wissen-card-title: clamp(1.25rem, calc(1.154412rem + .294118vw), 1.375rem);
  --wissen-hero-body: clamp(1rem, calc(.904412rem + .294118vw), 1.125rem);
  --site-hero-heading-size: var(--wissen-hero);
  --site-section-heading-size: var(--wissen-section-title);
  --site-hero-copy-size: var(--wissen-hero-body);
  --site-section-copy-size: 1rem;
  background: var(--wissen-bg);
}
html[data-wissen-global] body.wissen-global-type main > section,
html[data-wissen-global] body.wissen-global-type footer.wf {
  background: var(--wissen-bg);
}
html[data-wissen-global] body.wissen-global-type :is(.ad-ref-hero,.ins-hero)::before {
  background: none;
}
html[data-wissen-global] body.wissen-global-type .m6-cta-bg { display: none; }
/* Restore the original orbit/glow background for the Ready to transform CTA. */
html[data-wissen-global] body.wissen-global-type .m6-cta[aria-labelledby="contact-heading"] .m6-cta-bg { display: block; }
/* Contain the orbit's decorative glow so it cannot widen the mobile page. */
html[data-wissen-global] body.wissen-global-type .ao-hero { overflow: clip; }

/* Explicit text roles keep navigation, phone mock-ups and metric values separate.
 * Importance is limited to these mapped roles because the legacy theme forces
 * several old scales with !important. User styles can still override them. */
html[data-wissen-global] body.wissen-global-type main [data-wissen-type] {
  overflow-wrap: anywhere;
}
html[data-wissen-global] body.wissen-global-type main [data-wissen-type="hero-title"] {
  font-size: var(--wissen-hero) !important;
  line-height: 1.1 !important;
